INSERT INTO dtb_payment (id, payment_method, charge, rule_min, rule_max, visible, create_date, update_date, discriminator_type)
SELECT CAST(JSON_VALUE(CAST(:payment AS CHAR), '$.paymentId') AS UNSIGNED), JSON_VALUE(CAST(:payment AS CHAR), '$.paymentMethodName'), CAST(JSON_VALUE(CAST(:payment AS CHAR), '$.charge') AS SIGNED), CAST(JSON_VALUE(CAST(:payment AS CHAR), '$.ruleMin') AS SIGNED), CAST(JSON_VALUE(CAST(:payment AS CHAR), '$.ruleMax') AS SIGNED), IF(LOWER(JSON_VALUE(CAST(:payment AS CHAR), '$.visible')) IN ('true', '1'), 1, 0), NOW(), NOW(), 'payment'
WHERE JSON_VALUE(CAST(:payment AS CHAR), '$.paymentId') REGEXP '^[0-9]+$'
ON DUPLICATE KEY UPDATE payment_method=VALUES(payment_method), charge=VALUES(charge), rule_min=VALUES(rule_min), rule_max=VALUES(rule_max), visible=VALUES(visible), update_date=NOW()
